def get_sequence(n_terms):
    a = [0] * n_terms
    for i in range(n_terms):
        if (i + 1) & (i) == 0 and (i + 1) > 0: # This is not correct for 2^i - 1
            pass
    # Let's use a simpler sequence: a_n = 1 if n+1 is a power of 2, else 0
    a = [0] * n_terms
    for i in range(n_terms):
        val = i + 1
        if (val & (val - 1)) == 0 and val > 0:
            a[i] = 1
    return a

def count_tuples(a, k):
    tuples = set()
    for i in range(len(a) - k):
        tuples.add(tuple(a[i:i+k]))
    return len(tuples)

for k in range(1, 7):
    # We need to choose enough terms to ensure all tuples are counted.
    # For a_n = 0, 1, 0, 0, 1, 0, 0, 0, 1, ..., the sequence of 1s is at 2^i - 1.
    # The distance between 1s is increasing.
    # Let's use a large number of terms.
    a = get_sequence(2000)
    print(f"k={k}, count={count_tuples(a, k)}")
